{
  "items": [
    {
      "name": "lp.norm_eq_tsum_rpow",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "theorem",
      "type": "∀ {α : Type u_3} {E : α → Type u_4} {p : ENNReal} [inst : (i : α) → NormedAddCommGroup (E i)],\n  0 < p.toReal → ∀ (f : ↥(lp E p)), ‖f‖ = (∑' (i : α), ‖↑f i‖ ^ p.toReal) ^ (1 / p.toReal)"
    },
    {
      "name": "PiLp.nnnorm_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.PiLp",
      "kind": "theorem",
      "type": "∀ {ι : Type u_2} {β : ι → Type u_4} [inst : Fintype ι] [inst_1 : (i : ι) → SeminormedAddCommGroup (β i)] (x : PiLp 1 β),\n  ‖x‖₊ = ∑ i, ‖x.ofLp i‖₊"
    },
    {
      "name": "lp.norm_rpow_eq_tsum",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "theorem",
      "type": "∀ {α : Type u_3} {E : α → Type u_4} {p : ENNReal} [inst : (i : α) → NormedAddCommGroup (E i)],\n  0 < p.toReal → ∀ (f : ↥(lp E p)), ‖f‖ ^ p.toReal = ∑' (i : α), ‖↑f i‖ ^ p.toReal"
    },
    {
      "name": "lp.instNormSubtypePreLpMemAddSubgroup",
      "module_name": "Mathlib.Analysis.Normed.Lp.lpSpace",
      "kind": "instance",
      "type": "{α : Type u_3} → {E : α → Type u_4} → {p : ENNReal} → [inst : (i : α) → NormedAddCommGroup (E i)] → Norm ↥(lp E p)"
    },
    {
      "name": "MeasureTheory.L1.norm_eq_integral_norm",
      "module_name": "Mathlib.MeasureTheory.Integral.Bochner.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {m : MeasurableSpace α} {μ : MeasureTheory.Measure α} {H : Type u_6} [inst : NormedAddCommGroup H]\n  (f : ↥(MeasureTheory.Lp H 1 μ)), ‖f‖ = ∫ (a : α), ‖↑↑f a‖ ∂μ"
    },
    {
      "name": "WithLp.prod_norm_eq_of_L1",
      "module_name": "Mathlib.Analysis.Normed.Lp.ProdLp",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SeminormedAddCommGroup α] [inst_1 : SeminormedAddCommGroup β]\n  (x : WithLp 1 (α × β)), ‖x‖ = ‖x.fst‖ + ‖x.snd‖"
    },
    {
      "name": "MeasureTheory.L1.SimpleFunc.norm_eq_integral",
      "module_name": "Mathlib.MeasureTheory.Integral.Bochner.L1",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {E : Type u_2} [inst : NormedAddCommGroup E] {m : MeasurableSpace α} {μ : MeasureTheory.Measure α}\n  (f : ↥(MeasureTheory.Lp.simpleFunc E 1 μ)),\n  ‖f‖ =\n    MeasureTheory.SimpleFunc.integral μ (MeasureTheory.SimpleFunc.map norm (MeasureTheory.Lp.simpleFunc.toSimpleFunc f))"
    }
  ]
}
